example.programlisting:
using System;
using System.Collections.Generic;
using Rexx.Net;

using var rexx = RexxInterpreter.Create();
rexx.Local["NAMES"] = new List<string> { "b", "a" };
Console.WriteLine(rexx.Run<string>(
    "l = .names; l~Add('c'); l~Sort\n" +
    "return l~Count l[0] .net~typeOf(l)"));
Console.WriteLine(rexx.Run<int>("return .net~type('Helpers')~Twice(21)"));
Console.WriteLine(rexx.Run<string>("d = .directory~new; d~name = 'Ann'\n" +
                                   "return .net~type('Helpers')~Describe(d)"));
try { rexx.Run("return .net~type('Helpers')~Fails"); }
catch (RexxException e) { Console.WriteLine($"{e.Code} {e.InnerException?.Message}"); }

public static class Helpers
{
    // .NET code called from Rexx, calling Rexx back
    public static int Twice(int x) => RexxInterpreter.Current!.Run<int>("use arg x; return 2 * x", x);
    public static string Describe(RexxObject d) => $"{d.Send("NAME")} ({d.Send<int>("ITEMS")} item)";
    public static int Fails() => throw new InvalidOperationException("no way");
}
